values ('ella', 'Ella', 'Hill Country', 'Mist, tea terraces and the bridge in the sky', 'A small hill-country town surrounded by tea estates and walking trails, reached by one of the world''s most scenic railway journeys.', array['Set at roughly 1,000 metres in the Badulla District, Ella is surrounded by steep green valleys, tea estates and waterfalls. Cooler air and easy walks make it a favourite pause in any itinerary.', 'The Nine Arches Bridge at Demodara, a colonial-era railway viaduct built from stone, brick and cement, is one of the island''s most photographed sights, best seen when a train curves across it through the jungle.', 'The railway journey from Kandy or Nanu Oya to Ella winds through tea country, tunnels and cloud forest. Reserved seats are limited and sell quickly, so tickets are subject to availability.']::text[], '[{"title":"Nine Arches Bridge","text":"A short walk through tea and forest leads to viewpoints over the viaduct; train times vary."},{"title":"Little Adam''s Peak","text":"An easy hike of about an hour with sweeping views across the Ella Gap."},{"title":"The hill-country train","text":"A slow, beautiful ride past tea estates and misty ridges, often counted among the world''s great rail journeys."},{"title":"Ravana Falls","text":"A tiered waterfall beside the road below Ella, at its fullest after rain."}]'::jsonb, 'Generally driest from January to April. Mist and showers are possible at any time of year, and evenings can be cool.', 'By train from Kandy or Nanu Oya, or around 5 to 6 hours by road from Kandy. Roughly 2 to 3 hours by road to Yala.', array['nature', 'rail']::public.interest[], 'ellaAerial', array['ellaTrain', 'teaPlucking']::text[], 6.8667, 81.0466, 2, true)
