values ('yala', 'Yala', 'Deep South', 'Leopards, elephants and wild coastal scrub', 'Explore Yala National Park by jeep in search of leopards, elephants, sloth bears and remarkable birdlife in Sri Lanka''s dry south-east.', array['Yala National Park stretches across scrub jungle, lagoons, rocky outcrops and coastline in the island''s south-east. It is one of Sri Lanka''s most visited parks and is renowned for its leopards, alongside Asian elephants, sloth bears, crocodiles, water buffalo, spotted deer and peafowl.', 'Safaris take place by jeep, usually in the early morning and late afternoon when animals are most active. Sightings are never guaranteed, and a respectful driver who keeps a proper distance makes for a better experience for visitors and wildlife alike.', 'Parts of the park have historically closed for several weeks late in the dry season, often around September and October. Closure dates vary, so they are confirmed before any safari is booked.']::text[], '[{"title":"Morning jeep safari","text":"Enter at opening time for cooler air and the best chance of seeing wildlife on the move."},{"title":"Birdlife","text":"Painted storks, bee-eaters, eagles and waders gather around the park''s lagoons and waterholes."},{"title":"Coastal landscapes","text":"Rocky outcrops, dunes and empty beaches give the park a character unlike any other in Sri Lanka."},{"title":"Responsible wildlife viewing","text":"We favour unhurried safaris that respect park rules and give animals space."}]'::jsonb, 'Usually best from around February to June, when water is scarcer and animals gather. Check seasonal closures before booking.', 'Around 2 to 3 hours by road from Ella, or about 4 to 5 hours from Colombo via the Southern Expressway.', array['wildlife', 'nature']::public.interest[], 'yalaLeopard', array['safariElephant', 'minneriyaElephants']::text[], 6.42, 81.42, 4, true)
