delete from public.experience_destinations where experience_id = (select id from public.experiences where slug = 'leopard-and-elephant-safaris');
values ('hill-country-rail-journey', 'The Hill-Country Rail Journey', 'rail', 'Ride the celebrated railway through tea country and cloud forest to Ella, with your vehicle meeting you at the other end.', array['The railway from Kandy through Nanu Oya to Ella climbs through tea estates, tunnels and misty ridges. It is slow, open-windowed and quite unlike any road journey.', 'Your driver takes your luggage by road and meets you at the station, so you can travel light and simply enjoy the view.']::text[], array['A scenic train journey of several hours through the highlands', 'Views of tea estates, waterfalls and mountain villages', 'Station pick-up by your driver on arrival']::text[], array['Reserved seats are limited and released on a fixed schedule; tickets are subject to availability.', 'Trains frequently run late. We build in flexibility.', 'The most popular stretch is between Nanu Oya and Ella.']::text[], 'Half day to full day', 'ellaTrain', 2, true)
