values ('cultural-triangle-and-kandy', 'Cultural Triangle & Kandy', 'A short, rich introduction to Sri Lanka''s ancient cities and its last royal capital.', array['Ideal for a first visit or a short stopover, this journey combines the rock fortress of Sigiriya and the cave temple of Dambulla with the temples, lake and gardens of Kandy.', 'Every itinerary is private and can be adjusted: add a night, swap a visit or slow the pace.']::text[], 5, 'Culture & heritage', array['culture', 'nature']::public.interest[], 'Bandaranaike International Airport (CMB), or any hotel in Colombo or Negombo. Alternative pickup points can be arranged.', array['Private air-conditioned vehicle with an English-speaking chauffeur-guide', 'Airport pickup and drop-off', 'Fuel, highway tolls and parking', 'Bottled water in the vehicle']::text[], array['Hotels', 'Meals', 'Entrance fees', 'Safari jeeps', 'International flights', 'Visa / ETA', 'Tips']::text[], 'dambullaCave', true, 0, true)
