values ('hill-country-rail-and-southern-shores', 'Hill Country Rail & Southern Shores', 'Kandy, tea country and the scenic train to Ella, ending with Galle Fort and the southern coast.', array['This week-long journey follows the island''s most scenic route: from Kandy into the cool tea country, by train to Ella, then down to the coast and the ramparts of Galle.', 'Train seats are subject to availability; if reserved seats cannot be secured we travel the same route by road.']::text[], 7, 'Scenic & coastal', array['rail', 'nature', 'beach', 'culture']::public.interest[], 'Bandaranaike International Airport (CMB), or any hotel in Colombo or Negombo. Alternative pickup points can be arranged.', array['Private air-conditioned vehicle with an English-speaking chauffeur-guide', 'Airport pickup and drop-off', 'Fuel, highway tolls and parking', 'Bottled water in the vehicle']::text[], array['Hotels', 'Meals', 'Entrance fees', 'Safari jeeps', 'International flights', 'Visa / ETA', 'Tips']::text[], 'ellaTrain', true, 1, true)
