values ('classic-sri-lanka', 'Classic Sri Lanka', 'Ancient cities, the hill country, a Yala safari and Galle: the island''s highlights in ten days.', array['Our most balanced journey brings together the island''s great themes: heritage in the Cultural Triangle, tea and rail in the highlands, wildlife in Yala and history on the southern coast.', 'Pacing allows for two nights in most places, with time to rest between the highlights.']::text[], 10, 'Highlights', array['culture', 'wildlife', 'rail', 'nature', 'beach']::public.interest[], 'Bandaranaike International Airport (CMB), or any hotel in Colombo or Negombo. Alternative pickup points can be arranged.', array['Private air-conditioned vehicle with an English-speaking chauffeur-guide', 'Airport pickup and drop-off', 'Fuel, highway tolls and parking', 'Bottled water in the vehicle']::text[], array['Hotels', 'Meals', 'Entrance fees', 'Safari jeeps', 'International flights', 'Visa / ETA', 'Tips']::text[], 'minneriyaElephants', true, 2, true)
