values ('ancient-kingdoms-and-wild-places', 'Ancient Kingdoms & Wild Places', 'Anuradhapura, Polonnaruwa and Sigiriya, the highlands and two safari regions, ending on the southern coast.', array['For travellers with a deeper interest in history and wildlife, this journey adds the ancient sacred city of Anuradhapura and the medieval capital of Polonnaruwa, with safaris in both the north-central plains and Yala.', 'The pace is relaxed, with time on the coast at the end.']::text[], 12, 'Heritage & wildlife', array['culture', 'wildlife', 'nature', 'rail', 'beach']::public.interest[], 'Bandaranaike International Airport (CMB), or any hotel in Colombo or Negombo. Alternative pickup points can be arranged.', array['Private air-conditioned vehicle with an English-speaking chauffeur-guide', 'Airport pickup and drop-off', 'Fuel, highway tolls and parking', 'Bottled water in the vehicle']::text[], array['Hotels', 'Meals', 'Entrance fees', 'Safari jeeps', 'International flights', 'Visa / ETA', 'Tips']::text[], 'safariElephant', true, 3, true)
