values ('grand-tour-of-sri-lanka', 'The Grand Tour of Sri Lanka', 'Fifteen unhurried days through ancient cities, cloud forest, wildlife parks and the southern coast.', array['Our most complete journey gives time for everything: the ancient cities, Kandy, the highlands including Horton Plains, a Yala safari, whale watching in season, and several restful days by the sea.', 'It is a natural starting point for a fully tailored itinerary.']::text[], 15, 'Comprehensive', array['culture', 'wildlife', 'nature', 'rail', 'beach', 'wellness']::public.interest[], 'Bandaranaike International Airport (CMB), or any hotel in Colombo or Negombo. Alternative pickup points can be arranged.', array['Private air-conditioned vehicle with an English-speaking chauffeur-guide', 'Airport pickup and drop-off', 'Fuel, highway tolls and parking', 'Bottled water in the vehicle']::text[], array['Hotels', 'Meals', 'Entrance fees', 'Safari jeeps', 'International flights', 'Visa / ETA', 'Tips']::text[], 'galleLighthouse', true, 4, true)
